import Foundation

@main
enum MatrixFirmwareArtwork {
    static func main() throws {
        func rgb(_ color: RGB) -> String { "{\(color.r),\(color.g),\(color.b)}" }
        func pixels(_ colors: [RGB]) -> String { "{" + colors.map(rgb).joined(separator: ",") + "}" }
        let icons = MatrixIcon.allCases + [.off]
        var text = """
        // Generated by scripts/generate-matrix-firmware-artwork.sh; do not edit.
        #pragma once
        #include <stdint.h>
        #include <stddef.h>
        namespace MatrixArtwork {
        struct Icon { const char* name; uint64_t mask; uint8_t pixels[64][3]; };
        static const Icon icons[] = {

        """
        text += icons.map {
            "{\"" + $0.rawValue + "\",UINT64_C(0x" + String($0.bitmap, radix: 16) + ")," +
                pixels($0.artwork(at: 0)) + "}"
        }.joined(separator: ",\n")
        text += "\n};\nstatic constexpr size_t IconCount = sizeof(icons)/sizeof(icons[0]);\n"
        text += "static const uint8_t afk[3][64][3] = {\n"
        text += (0..<3).map { pixels(MatrixIcon.afk.artwork(at: Double($0) * 0.8 + 0.001)) }
            .joined(separator: ",\n") + "\n};\n"
        text += "static constexpr size_t ShrugWidth = \(MatrixIconAnimation.shrugWidth);\n"
        text += "static const uint8_t shrug[8][ShrugWidth][3] = {\n"
        text += (0..<8).map { row in
            pixels(MatrixIconAnimation.shrugRows[row].map {
                !$0 ? .off : row < 3 ? RGB(r: 255, g: 245, b: 220) : RGB(r: 255, g: 210, b: 20)
            })
        }.joined(separator: ",\n") + "\n};\n"
        text += "static const uint8_t gamma[256] = {"
        text += (0...255).map { String(MatrixColorCalibration.linearized(RGB(r: UInt8($0), g: 0, b: 0)).r) }
            .joined(separator: ",") + "};\n}\n"
        try text.write(toFile: CommandLine.arguments[1], atomically: true, encoding: .utf8)
    }
}
